impl FaceIdentity {
	pub fn to_json(&self) -> String {
		let mut s = String::new();
		self.to_json_into(&mut s);
		s
	}
	pub fn to_text(&self) -> String {
		let mut s = String::new();
		self.to_text_into(&mut s);
		s
	}
	pub fn to_cbor(&self) -> Vec<u8> {
		let mut v = Vec::new();
		self.to_cbor_into(&mut v);
		v
	}
	pub(crate) fn to_json_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("\"digest\":");
		out.push('[');
		let mut v33 = true;
		for v32 in self.digest.iter() {
			if !v33 {
				out.push(',');
			}
			v33 = false;
			let _ = write!(out, "{}", v32);
		}
		out.push(']');
		out.push(',');
		out.push_str("\"index\":");
		let _ = write!(out, "{}", self.index);
		out.push('}');
	}
	pub(crate) fn to_text_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("digest=");
		out.push('[');
		let mut v35 = true;
		for v34 in self.digest.iter() {
			if !v35 {
				out.push_str(", ");
			}
			v35 = false;
			let _ = write!(out, "{}", v34);
		}
		out.push(']');
		out.push_str(", ");
		out.push_str("index=");
		let _ = write!(out, "{}", self.index);
		out.push('}');
	}
	pub(crate) fn to_cbor_into(&self, out: &mut Vec<u8>) {
		crate::codec::cbor::map(out, 2);
		crate::codec::cbor::text(out, "digest");
		crate::codec::cbor::array(out, self.digest.len());
		for v36 in self.digest.iter() {
			crate::codec::cbor::uint(out, *v36 as u64);
		}
		crate::codec::cbor::text(out, "index");
		crate::codec::cbor::uint(out, self.index as u64);
	}
}

